const input = require("fs").readFileSync(0, "utf8");
const words = input.trim().split(/\s+/);

class TrieNode {
  constructor() {
    this.children = new Map();
    this.isEnd = false;
    this.count = 0;
  }
}

function insert(root, word) {
  let node = root;
  for (const ch of word) {
    if (!node.children.has(ch)) {
      node.children.set(ch, new TrieNode());
    }
    node = node.children.get(ch);
    node.count++;
  }
  node.isEnd = true;
}

function uniquePrefix(root, word) {
  let node = root;
  for (let i = 0; i < word.length; i++) {
    node = node.children.get(word[i]);
    if (node.count === 1) {
      return word.slice(0, i + 1);
    }
  }
  return word;
}

const root = new TrieNode();
for (const word of words) {
  insert(root, word);
}
for (const word of words) {
  console.log(`${word}: ${uniquePrefix(root, word)}`);
}

steps.body:
For autocomplete, walk down to the prefix's node, then explore everything below it with a depth-first search that carries the letters so far. Every node with `isEnd` set completes a word:

```javascript harness
class TrieNode {
  constructor() {
    this.children = new Map();
    this.isEnd = false;
  }
}
const root = new TrieNode();
for (const word of ["car", "cat", "card", "dog"]) {
  let node = root;
  for (const ch of word) {
    if (!node.children.has(ch)) {
      node.children.set(ch, new TrieNode());
    }
    node = node.children.get(ch);
  }
  node.isEnd = true;
}
const start = root.children.get("c").children.get("a");
const out = [];
{{code}}
collect(start, "ca");
console.log(out.join(" "));
```

```javascript
function collect(node, word) {
  if (node.isEnd) {
    out.push(word);
  }
  for (const [ch, child] of node.children) {
    collect(child, word + ch);
  }
}
```

A Map iterates in insertion order, not alphabetical order, so that run prints `car card cat`, in the order the letters were first added. For alphabetical results, sort what you collect, or visit the children in sorted order with `[...node.children.keys()].sort()`. Then a word comes before the longer words below it, the list comes out alphabetical, and you can stop as soon as you have as many as you need.

**The gotcha:** `word + ch` makes a new string for each call, so nothing needs undoing on the way back. If you build the word in a shared array instead, `pop()` after each child.

example.code:
const input = require("fs").readFileSync(0, "utf8");
const [first, ...queries] = input.trim().split("\n");

class TrieNode {
  constructor() {
    this.children = new Map();
    this.isEnd = false;
  }
}

class Trie {
  constructor() {
    this.root = new TrieNode();
  }

  insert(word) {
    let node = this.root;
    for (const ch of word) {
      if (!node.children.has(ch)) {
        node.children.set(ch, new TrieNode());
      }
      node = node.children.get(ch);
    }
    node.isEnd = true;
  }

  find(prefix) {
    let node = this.root;
    for (const ch of prefix) {
      if (!node.children.has(ch)) {
        return null;
      }
      node = node.children.get(ch);
    }
    return node;
  }
}

function collect(node, word, out) {
  if (node.isEnd) {
    out.push(word);
  }
  for (const ch of [...node.children.keys()].sort()) {
    collect(node.children.get(ch), word + ch, out);
  }
}

const trie = new Trie();
for (const word of first.trim().split(/\s+/)) {
  trie.insert(word);
}
for (const q of queries) {
  const prefix = q.trim();
  const node = trie.find(prefix);
  const out = [];
  if (node !== null) {
    collect(node, prefix, out);
  }
  console.log(`${prefix}: ${out.length > 0 ? out.join(" ") : "no matches"}`);
}

