steps.body:
Some searches let `.` stand for any one letter, so `c.t` matches `cat` and `cut`. A plain walk can't follow a dot, because it doesn't know which child to take. Search recursively instead, passing the node and the index of the next letter in the pattern, and at a dot try every child:

```javascript harness
class TrieNode {
  constructor() {
    this.children = new Map();
    this.isEnd = false;
  }
}
const root = new TrieNode();
for (const word of ["cat", "cut", "cart"]) {
  let node = root;
  for (const ch of word) {
    if (!node.children.has(ch)) {
      node.children.set(ch, new TrieNode());
    }
    node = node.children.get(ch);
  }
  node.isEnd = true;
}
{{code}}
console.log(matches(root, "c.t", 0), matches(root, "c.r", 0), matches(root, "c..t", 0));
```

```javascript
function matches(node, pattern, i) {
  if (i === pattern.length) {
    return node.isEnd;
  }
  const ch = pattern[i];
  if (ch === ".") {
    for (const child of node.children.values()) {
      if (matches(child, pattern, i + 1)) {
        return true;
      }
    }
    return false;
  }
  const child = node.children.get(ch);
  return child !== undefined && matches(child, pattern, i + 1);
}
```

With `cat`, `cut`, and `cart` stored, `c.t` and `c..t` match, but `c.r` doesn't. The path through `c`, `a`, and `r` exists, but at the end of the pattern a word must end at that node, and `cart` goes on. A letter follows one child, like a plain search. A dot can branch into every child, up to 26 for lowercase words, so a pattern with `d` dots can try up to `26 ** d` paths, never more than the trie holds. An all-dot pattern can visit every node down to its length, while each real letter cuts the search back to one branch.

**The gotcha:** `forEach` can't stop early. A `return true` inside its callback only leaves the callback, and the function keeps going. Loop with `for...of` and return from there, or use `[...node.children.values()].some(...)`.

example.code:
const input = require("fs").readFileSync(0, "utf8");
const [first, ...patterns] = input.trim().split("\n");

class TrieNode {
  constructor() {
    this.children = new Map();
    this.isEnd = false;
  }
}

function insert(root, word) {
  let node = root;
  for (const ch of word) {
    if (!node.children.has(ch)) {
      node.children.set(ch, new TrieNode());
    }
    node = node.children.get(ch);
  }
  node.isEnd = true;
}

function collectMatches(node, pattern, i, word, out) {
  if (i === pattern.length) {
    if (node.isEnd) {
      out.push(word);
    }
    return;
  }
  const ch = pattern[i];
  if (ch === ".") {
    for (const next of [...node.children.keys()].sort()) {
      collectMatches(node.children.get(next), pattern, i + 1, word + next, out);
    }
  } else if (node.children.has(ch)) {
    collectMatches(node.children.get(ch), pattern, i + 1, word + ch, out);
  }
}

const root = new TrieNode();
for (const word of first.trim().split(/\s+/)) {
  insert(root, word);
}
for (const p of patterns) {
  const pattern = p.trim();
  const out = [];
  collectMatches(root, pattern, 0, "", out);
  console.log(`${pattern}: ${out.length > 0 ? out.join(" ") : "no words"}`);
}

